import React from "react";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import {
  BK, Bottom, F, GREY, INK, INOUT, IcoCheck, IcoPin, IcoUser, Lines, OR, PAPER, RED, Row, SHADOW, Shot, WH,
  bump, cl, img, io, k, lin, pop, txtIn,
} from "./GmnTope";

// DIGITALL MAX 2 · copies 1 e 2 do GMN TOPE 3 (19/10, tarde). O o diretor achou estranho a voz falar "GMN Tope 03":
// a narração diz "o nosso método" e o nome aparece só escrito. Voz o locutor sem pausas (edit/voz-copyN-sem-pausas.wav).
// Mesma identidade e peças da v1 (GmnTope.tsx). Cada copy abre com um recurso diferente da v1 (lista do Maps):
// copy 1 = semana perdendo dinheiro; copy 2 = ficha da empresa apagada.
// Tempos = tempos da voz sem pausas (t = 0 é o começo do wav; o vídeo tem LEAD de entrada).

export const CP_FPS = 30;
const LEAD = 0.2;
export const CP1_FRAMES = Math.round(24.6 * CP_FPS);
export const CP2_FRAMES = Math.round(24.2 * CP_FPS);

type Sc = [number, React.FC<{ t: number }>, (p: number) => string];
const Seq: React.FC<{ scenes: Sc[] }> = ({ scenes }) => {
  const t = useCurrentFrame() / CP_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: BK }}>
      {scenes.map(([at, S, clip], i) => {
        const end = i + 1 < scenes.length ? scenes[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.38], [0, 1], { ...cl, easing: INOUT });
        // câmera de cada cena: aproxima devagar do começo ao fim (a primeira abre com um recuo rápido)
        const a0 = Math.max(at, 0), a1 = i + 1 < scenes.length ? scenes[i + 1][0] + 0.45 : a0 + 4.5;
        const z = 1 + 0.07 * lin(t, a0, a1) + (i === 0 ? 0.22 * (1 - k(t, -0.2, 0.7)) : 0);
        const dy = Math.sin((t - a0) * 1.3) * 10;
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <AbsoluteFill style={{ transform: `scale(${z.toFixed(4)}) translateY(${dy.toFixed(1)}px)` }}>
              <S t={t} />
            </AbsoluteFill>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};
const W = {
  circle: (p: number) => `circle(${(p * 125).toFixed(1)}% at 50% 50%)`,
  up: (p: number) => `inset(${((1 - p) * 100).toFixed(2)}% 0 0 0)`,
  down: (p: number) => `inset(0 0 ${((1 - p) * 100).toFixed(2)}% 0)`,
  left: (p: number) => `inset(0 0 0 ${((1 - p) * 100).toFixed(2)}%)`,
  right: (p: number) => `inset(0 ${((1 - p) * 100).toFixed(2)}% 0 0)`,
  diag: (p: number) => `polygon(0 0, ${(p * 170).toFixed(1)}% 0, ${(p * 170 - 60).toFixed(1)}% 100%, 0 100%)`,
  diag2: (p: number) => `polygon(${(100 - p * 170).toFixed(1)}% 0, 100% 0, 100% 100%, ${(160 - p * 170).toFixed(1)}% 100%)`,
  split: (p: number) => `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)`,
  band: (p: number) => `inset(${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}% 0)`,
  diamond: (p: number) => `polygon(50% ${(50 - p * 110).toFixed(1)}%, ${(50 + p * 110).toFixed(1)}% 50%, 50% ${(50 + p * 110).toFixed(1)}%, ${(50 - p * 110).toFixed(1)}% 50%)`,
  corner: (p: number) => `circle(${(p * 150).toFixed(1)}% at 100% 100%)`,
  corner2: (p: number) => `circle(${(p * 150).toFixed(1)}% at 0% 0%)`,
};

// ───────── peças ─────────
