  <div style={{ width: s, height: s, borderRadius: s, background: OR, border: `${s * 0.08}px solid #C98200`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 900, fontSize: s * 0.42, color: BK }}>R$</div>
);
const BigX: React.FC<{ s: number }> = ({ s }) => (
