);
const Search: React.FC<{ t: number; at: number; q: string; typeA: number; typeB: number }> = ({ t, at, q, typeA, typeB }) => {
  const bar = pop(t, at, 0.5);
  const n = Math.round(q.length * lin(t, typeA, typeB));
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top: 560, height: 140, borderRadius: 140, background: WH, display: "flex", alignItems: "center", gap: 24, padding: "0 44px", boxSizing: "border-box", opacity: Math.min(1, bar * 2), transform: `translateY(${((1 - bar) * 200 + Math.sin(t * 2.3) * 8).toFixed(1)}px) scale(${(0.9 + 0.1 * bar).toFixed(4)})` }}>
      <svg width={60} height={60} viewBox="0 0 24 24" fill="none" stroke={OR} strokeWidth={2.8} strokeLinecap="round"><circle cx="10.5" cy="10.5" r="6.5" /><path d="M15.5 15.5L21 21" /></svg>
      <span style={{ fontFamily: F, fontWeight: 700, fontSize: 44, color: n ? INK : "#A9A9A9", whiteSpace: "nowrap", overflow: "hidden" }}>{n ? q.slice(0, n) : "Pesquisar"}</span>
    </div>
  );
};
