      </div>
      <div style={{ padding: `${u * 5}px ${u * 6}px ${u * 6}px` }}>
        <div style={{ fontWeight: 800, fontSize: u * 7.2, color: on > 0.5 ? INK : "#777", letterSpacing: "-0.03em" }}>{name}</div>
        <div style={{ width: u * 52, height: u * 2.4, borderRadius: u, background: on > 0.5 ? "#E4E1DA" : "#2A2A2A", marginTop: u * 3.4 }} />
        <div style={{ width: u * 36, height: u * 2.4, borderRadius: u, background: on > 0.5 ? "#E4E1DA" : "#2A2A2A", marginTop: u * 2.2 }} />
      </div>
