};
const Price: React.FC<{ t: number; at: number; size: number; dark?: boolean }> = ({ t, at, size, dark }) => {
  const e = pop(t, at, 0.5);
  return (
    <div style={{ display: "flex", alignItems: "flex-start", fontFamily: F, fontWeight: 900, color: dark ? BK : OR, letterSpacing: "-0.05em", lineHeight: 1, opacity: Math.min(1, e * 2), transform: `scale(${(1.5 - 0.5 * e + 0.05 * bump(t, at + 0.45, 0.35)).toFixed(4)})` }}>
      <span style={{ fontSize: size * 0.36, marginTop: size * 0.1, marginRight: size * 0.04 }}>R$</span>
      <span style={{ fontSize: size }}>10</span>
    </div>
