};
const Button: React.FC<{ t: number; at: number; tapAt: number; label: string; dark?: boolean }> = ({ t, at, tapAt, label, dark }) => {
  const b = pop(t, at, 0.5);
  const tap = bump(t, tapAt, 0.4);
  const bg = dark ? BK : OR;
  return (
    <div style={{ position: "relative", background: bg, color: dark ? OR : BK, fontFamily: F, fontWeight: 900, fontSize: 52, whiteSpace: "nowrap", padding: "32px 64px", borderRadius: 120, opacity: Math.min(1, b * 2), transform: `scale(${(b * (1 - 0.06 * tap)).toFixed(4)})`, boxShadow: dark ? "0 24px 60px rgba(0,0,0,0.35)" : `0 0 ${(50 + 30 * Math.sin(t * 4)).toFixed(0)}px rgba(242,159,5,0.45)` }}>
      {label}
      {t > tapAt && t < tapAt + 0.8 ? <div style={{ position: "absolute", inset: -lin(t, tapAt, tapAt + 0.8) * 60, borderRadius: 200, border: `6px solid ${bg}`, opacity: 1 - lin(t, tapAt, tapAt + 0.8) }} /> : null}
    </div>
  );
};
const Center: React.FC<{ top: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", ...style }}>{children}</div>
);

