// ───────── vitrine: a tela ocupa o quadro e a câmera passeia por ela ─────────
// cam: [tempo, foco x (0–1), foco y (0–1), zoom]; zoom 1 = imagem com 1000 px de largura
export type Cam = [number, number, number, number][];
export const camAt = (t: number, cam: Cam) => {
  if (t <= cam[0][0]) return cam[0].slice(1) as [number, number, number];
  for (let i = 0; i + 1 < cam.length; i++) {
    const [a, ...p] = cam[i];
    const [b, ...q] = cam[i + 1];
    if (t <= b) {
      const e = io(t, a, b);
      return p.map((v, j) => v + (q[j] - v) * e) as [number, number, number];
    }
  }
  return cam[cam.length - 1].slice(1) as [number, number, number];
};
export const Shot: React.FC<{ t: number; src: string; ar: number; cam: Cam; cy?: number; drift?: number }> = ({ t, src, ar, cam, cy = 760, drift = 1 }) => {
  const [fx, fy, z] = camAt(t, cam);
  const W = 1000 * z;
  const H = W / ar;
  // telas grandes não deixam faixa vazia: encostam no topo e nas laterais
  const fit = (v: number, size: number, lo: number, hi: number) => (size >= hi - lo ? Math.min(lo, Math.max(hi - size, v)) : v);
  const x = fit(540 - fx * W + Math.sin(t * 0.9) * 8 * drift, W, 0, 1080);
  const y = fit(cy - fy * H + Math.cos(t * 0.7) * 6 * drift, H, 0, 1480);
  return (
    <AbsoluteFill style={{ background: BK, overflow: "hidden" }}>
      <Img src={src} style={{ position: "absolute", inset: -80, width: 1240, height: 2080, objectFit: "cover", filter: "blur(46px) brightness(0.42) saturate(1.2)" }} />
      <Img src={src} style={{ position: "absolute", left: x, top: y, width: W, height: H, borderRadius: 26, boxShadow: "0 40px 120px rgba(0,0,0,0.6)" }} />
    </AbsoluteFill>
  );
};
