// v2 (19/10): narração sem nenhuma pausa (edit/voz-v2-sem-pausas.wav, 28,7 s). As cenas não foram reescritas: esta tabela
// (edit/mapa-v2.json, feita pelo tools/cortar_voz_v2.py) converte o tempo novo no tempo da v1; cada pausa tirada vira
// uma aceleração curta espalhada em ±0,15 s em volta dela.
const MAPA_V2: [number, number][] = [[0.0, 0.0], [1.997, 1.997], [2.299, 2.539], [4.639, 4.879], [4.941, 6.282], [8.543, 9.884], [8.845, 10.746], [11.366, 13.267], [11.668, 13.809], [14.909, 17.05], [15.211, 17.683], [16.971, 19.443], [17.273, 20.085], [20.784, 22.846], [21.086, 23.979], [22.005, 24.898], [22.307, 25.481], [25.317, 28.491], [25.619, 29.034], [28.328, 31.743], [28.63, 32.266], [38.944, 42.58]];
const mapa = (t: number, m: [number, number][]) => {
  if (t <= m[0][0]) return t;
  for (let i = 0; i + 1 < m.length; i++) {
    const [a0, b0] = m[i], [a1, b1] = m[i + 1];
    if (t <= a1) return b0 + ((t - a0) / (a1 - a0)) * (b1 - b0);
  }
  const [a, b] = m[m.length - 1];
  return b + (t - a);
};
export const DM2_V2_FRAMES = Math.round(30.4 * DM2_FPS);

export const DigitallMax2GmnTope: React.FC<{ v2?: boolean }> = ({ v2 }) => {
  const t0 = useCurrentFrame() / DM2_FPS - LEAD;
  const t = v2 ? mapa(t0, MAPA_V2) : t0;
  return (
    <AbsoluteFill style={{ background: BK }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

